/** Returns true when a customer has an erasure tombstone and must not regain PII. */
export async function isCustomerErased(merchantId: string, customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

/** Stable anonymized identity retained only for financial linkage after erasure. */
export function anonymizedCustomerSnapshot(customerId: string): Record<string, unknown> {
  return {
    id: customerId,
    email: erasedEmail(customerId),
    name: 'erased',
    phone: null,
    external_reference: erasedExternalReference(customerId),
    status: 'erased',
  };
}

export function erasedEmail(customerId: string): string {
  return `erased-${customerId}@erased.invalid`;
}

export function erasedExternalReference(customerId: string): string {
  return `erased-${customerId}`;
}
