{"path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","command":"create","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  max_attempts: number;
  idempotency_key: string;
  last_error: string | null;
  checkpoint: Record<string, unknown>;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ClaimedErasureRequest extends ErasureRequestRow {
  attemptToken: string;
}

export function toErasureResponse(row: ErasureRequestRow): Record<string, unknown> {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async findCustomer(merchantId: string, customerId: string): Promise<{ id: string; status: string } | undefined> {
    const result = await pool.query<{ id: string; status: string }>(
      `SELECT id,status FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,max_attempts,idempotency_key,last_error,checkpoint,
              created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,max_attempts,idempotency_key,last_error,checkpoint,
              created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findByIdempotencyKey(merchantId: string, idempotencyKey: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,max_attempts,idempotency_key,last_error,checkpoint,
              created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2`,
      [merchantId, idempotencyKey],
    );
    return result.rows[0];
  }

  async create(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3)
       RETURNING id,merchant_id,customer_id,status,attempts,max_attempts,idempotency_key,last_error,checkpoint,
                 created_at,updated_at,completed_at`,
      [merchantId, customerId, idempotencyKey],
    );
    return result.rows[0]!;
  }

  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status=CASE WHEN attempts >= max_attempts THEN 'failed' ELSE 'failed' END,
           available_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           last_error=COALESCE(last_error, 'worker_lease_expired'), updated_at=now()
       WHERE status='processing' AND lease_expires_at < now()`,
    );
    return result.rowCount ?? 0;
  }

  async claim(workerId: string, leaseSeconds = 120): Promise<ClaimedErasureRequest | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
           lease_expires_at=now()+($2 || ' seconds')::interval, last_error=NULL, updated_at=now()
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed') AND available_at<=now() AND attempts < max_attempts
         ORDER BY available_at, created_at
         FOR UPDATE SKIP LOCKED LIMIT 1
       )
       RETURNING id,merchant_id,customer_id,status,attempts,max_attempts,idempotency_key,last_error,checkpoint,
                 created_at,updated_at,completed_at`,
      [workerId, leaseSeconds],
    );
    const row = result.rows[0];
    if (!row) return undefined;
    return { ...row, attemptToken: workerId };
  }

  async saveCheckpoint(
    client: pg.PoolClient,
    requestId: string,
    checkpoint: Record<string, unknown>,
  ): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET checkpoint=$2, updated_at=now(),
           lease_expires_at=now()+interval '120 seconds'
       WHERE id=$1`,
      [requestId, checkpoint],
    );
  }

  async complete(client: pg.PoolClient, requestId: string, checkpoint: Record<string, unknown>): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', checkpoint=$2, completed_at=now(), updated_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, last_error=NULL
       WHERE id=$1`,
      [requestId, checkpoint],
    );
  }

  async fail(requestId: string, attempts: number, maxAttempts: number, errorCode: string): Promise<void> {
    const exhausted = attempts >= maxAttempts;
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',
           available_at=CASE WHEN $4 THEN now() ELSE now() + (LEAST(300, POWER(2, $2)) || ' seconds')::interval END,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           last_error=$3, updated_at=now()
       WHERE id=$1`,
      [requestId, attempts, errorCode, exhausted],
    );
  }

  async requeue(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='pending', available_at=now(), locked_by=NULL, locked_at=NULL,
           lease_expires_at=NULL, last_error=NULL, updated_at=now()
       WHERE id=$1 AND status IN ('failed','pending','processing') AND completed_at IS NULL`,
      [requestId],
    );
  }
}
"}

