{"path":"/workspace/source/apps/customer-service/src/erasure-service.ts","command":"create","file_text":"import { ErasureRepository, toErasureResponse, type ErasureRequestRow } from './erasure-repository.js';
import { transaction } from '../../../packages/database/src/pool.js';

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async createRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: Record<string, unknown> }> {
    const customer = await this.repository.findCustomer(merchantId, customerId);
    if (!customer) {
      throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    }

    const byKey = await this.repository.findByIdempotencyKey(merchantId, idempotencyKey);
    if (byKey) {
      if (byKey.customer_id !== customerId) {
        throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
      }
      if (byKey.status === 'failed') await this.repository.requeue(byKey.id);
      const refreshed = await this.repository.findById(merchantId, byKey.id) ?? byKey;
      return { status: 202, body: toErasureResponse(refreshed) };
    }

    const existing = await this.repository.findByCustomer(merchantId, customerId);
    if (existing) {
      if (existing.status === 'failed') await this.repository.requeue(existing.id);
      const refreshed = await this.repository.findById(merchantId, existing.id) ?? existing;
      return { status: 202, body: toErasureResponse(refreshed) };
    }

    try {
      const created = await transaction(async (client) => await this.repository.create(
        client, merchantId, customerId, idempotencyKey,
      ));
      return { status: 202, body: toErasureResponse(created) };
    } catch (error) {
      const code = (error as { code?: string }).code;
      if (code === '23505') {
        const raced = await this.repository.findByCustomer(merchantId, customerId)
          ?? await this.repository.findByIdempotencyKey(merchantId, idempotencyKey);
        if (raced) {
          if (raced.customer_id !== customerId) {
            throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
          }
          return { status: 202, body: toErasureResponse(raced) };
        }
      }
      throw error;
    }
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasureRequestRow> {
    const row = await this.repository.findById(merchantId, requestId);
    if (!row) throw Object.assign(new Error('erasure_request_not_found'), { statusCode: 404 });
    return row;
  }
}
"}

{"path":"/workspace/source/apps/customer-service/src/erasure-worker.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import { Redis } from 'ioredis';
import type pg from 'pg';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import {
  anonymizedCustomerSnapshot,
  erasedEmail,
  erasedExternalReference,
} from '../../../packages/privacy/src/erasure-guard.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureRepository,
  type ClaimedErasureRequest,
} from './erasure-repository.js';

const ANON_NAME = 'erased';
const ANON_BODY = '[erased]';

interface Checkpoint {
  tombstone?: boolean;
  customerCore?: boolean;
  paymentRecords?: boolean;
  notifications?: boolean;
  analytics?: boolean;
  documents?: boolean;
  searchCache?: boolean;
  mailpit?: boolean;
  provider?: boolean;
  outbox?: boolean;
  audit?: boolean;
}

function asCheckpoint(value: Record<string, unknown>): Checkpoint {
  return value as Checkpoint;
}

export class ErasureWorker {
  private lastLeaseRecovery = 0;

  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly workerId = `erasure-worker-${process.pid}-${Date.now()}`,
    private readonly redis = new Redis(config().REDIS_URL),
  ) {}

  async tick(): Promise<boolean> {
    if (Date.now() - this.lastLeaseRecovery > 30_000) {
      await this.repository.recoverExpiredLeases();
      this.lastLeaseRecovery = Date.now();
    }
    const job = await this.repository.claim(this.workerId);
    if (!job) return false;
    try {
      await this.process(job);
    } catch (error) {
      const code = stableErrorCode(error);
      logger.error({ error, requestId: job.id, code }, 'erasure request failed');
      await this.repository.fail(job.id, job.attempts, job.max_attempts, code);
    }
    return true;
  }

  async close(): Promise<void> {
    await this.redis.quit();
  }

  private async process(job: ClaimedErasureRequest): Promise<void> {
    let checkpoint = asCheckpoint(job.checkpoint ?? {});
    const merchantId = job.merchant_id;
    const customerId = job.customer_id;
    const destinations = await this.collectDestinations(merchantId, customerId);

    if (!checkpoint.tombstone) {
      await transaction(async (client) => {
        await client.query(
          `INSERT INTO customers.erasure_tombstones(customer_id,merchant_id,erasure_request_id)
           VALUES($1,$2,$3) ON CONFLICT(customer_id) DO NOTHING`,
          [customerId, merchantId, job.id],
        );
        checkpoint = { ...checkpoint, tombstone: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.customerCore) {
      await transaction(async (client) => {
        await this.eraseCustomerCore(client, merchantId, customerId);
        checkpoint = { ...checkpoint, customerCore: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.paymentRecords) {
      await transaction(async (client) => {
        await this.erasePaymentRecords(client, merchantId, customerId);
        checkpoint = { ...checkpoint, paymentRecords: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.notifications) {
      await transaction(async (client) => {
        await this.eraseNotifications(client, merchantId, customerId);
        checkpoint = { ...checkpoint, notifications: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.analytics) {
      await transaction(async (client) => {
        await this.eraseAnalytics(client, merchantId, customerId);
        checkpoint = { ...checkpoint, analytics: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.documents) {
      await this.eraseDocuments(merchantId, customerId);
      await transaction(async (client) => {
        checkpoint = { ...checkpoint, documents: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.searchCache) {
      await this.eraseSearchAndCache(merchantId, customerId);
      await transaction(async (client) => {
        checkpoint = { ...checkpoint, searchCache: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.mailpit) {
      for (const destination of destinations) {
        if (destination.includes('@')) await deleteMailpitMessagesForRecipient(destination);
      }
      await transaction(async (client) => {
        checkpoint = { ...checkpoint, mailpit: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.provider) {
      await transaction(async (client) => {
        await this.eraseProvider(client, merchantId, customerId);
        checkpoint = { ...checkpoint, provider: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.outbox) {
      await transaction(async (client) => {
        await this.eraseOutboxPayloads(client, merchantId, customerId);
        checkpoint = { ...checkpoint, outbox: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    if (!checkpoint.audit) {
      await transaction(async (client) => {
        await this.eraseAuditLogs(client, merchantId, customerId);
        checkpoint = { ...checkpoint, audit: true };
        await this.repository.saveCheckpoint(client, job.id, checkpoint);
      });
    }

    await transaction(async (client) => {
      await this.repository.complete(client, job.id, checkpoint);
    });
  }

  private async collectDestinations(merchantId: string, customerId: string): Promise<string[]> {
    const destinations = new Set<string>();
    const customer = await pool.query<{ email: string | null; phone: string | null }>(
      `SELECT email,phone FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    if (customer.rows[0]?.email) destinations.add(customer.rows[0].email);
    const contacts = await pool.query<{ value: string }>(
      `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of contacts.rows) destinations.add(row.value);
    const prefs = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of prefs.rows) destinations.add(row.destination);
    const emails = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of emails.rows) destinations.add(row.destination);
    const notifications = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of notifications.rows) destinations.add(row.destination);
    const refunds = await pool.query<{ customer_email: string | null }>(
      `SELECT r.customer_email FROM payments.refunds r
       JOIN payments.payment_intents p ON p.id=r.payment_intent_id
       WHERE p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of refunds.rows) if (row.customer_email) destinations.add(row.customer_email);
    return [...destinations];
  }

  private async eraseCustomerCore(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);

    const tickets = await client.query<{ ticket_id: string }>(
      `SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );
    for (const ticket of tickets.rows) {
      await client.query(
        `UPDATE customers.support_messages
         SET body=$3, attachments='[]'::jsonb, author_id=NULL
         WHERE merchant_id=$1 AND ticket_id=$2 AND author_type='customer'`,
        [merchantId, ticket.ticket_id, ANON_BODY],
      );
      await client.query(
        `UPDATE customers.support_tickets SET subject=$3 WHERE merchant_id=$1 AND id=$2`,
        [merchantId, ticket.ticket_id, ANON_BODY],
      );
      await client.query(`DELETE FROM customers.support_participants WHERE ticket_id=$1 AND customer_id=$2`, [
        ticket.ticket_id, customerId,
      ]);
    }

    await client.query(
      `UPDATE customers.customers
       SET email=$3, name=$4, phone=NULL, external_reference=$5, metadata='{}'::jsonb,
           status='erased', version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, erasedEmail(customerId), ANON_NAME, erasedExternalReference(customerId)],
    );
  }

  private async erasePaymentRecords(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const snapshot = anonymizedCustomerSnapshot(customerId);
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=$3, description=CASE WHEN description IS NULL THEN NULL ELSE $4 END, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, snapshot, ANON_BODY],
    );
    await client.query(
      `UPDATE payments.refunds r
       SET customer_email=$3
       FROM payments.payment_intents p
       WHERE r.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId, erasedEmail(customerId)],
    );
    await client.query(
      `UPDATE payments.disputes d
       SET evidence = COALESCE(d.evidence, '{}'::jsonb) - 'customerEmail' - 'email' - 'name' - 'phone' - 'customer'
       FROM payments.payment_intents p
       WHERE d.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=$3
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, snapshot],
    );
    await client.query(
      `UPDATE payments.payment_attempts a
       SET request_payload = COALESCE(a.request_payload, '{}'::jsonb) - 'customer' - 'email' - 'name' - 'phone',
           response_payload = CASE
             WHEN a.response_payload IS NULL THEN NULL
             ELSE COALESCE(a.response_payload, '{}'::jsonb) - 'customer' - 'email' - 'name' - 'phone'
           END
       FROM payments.payment_intents p
       WHERE a.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseNotifications(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.email_deliveries
       SET destination=$3, subject=$4, text_body=$4, html_body=$4,
           status=CASE WHEN status IN ('pending','failed','processing') THEN 'cancelled' ELSE status END,
           cancelled_at=CASE WHEN status IN ('pending','failed','processing') THEN now() ELSE cancelled_at END,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, erasedEmail(customerId), ANON_BODY],
    );
    await client.query(
      `UPDATE operations.notifications
       SET destination=$3, payload='{}'::jsonb, status=CASE WHEN status IN ('queued','retrying') THEN 'cancelled' ELSE status END,
           updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, erasedEmail(customerId)],
    );
  }

  private async eraseAnalytics(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL, properties='{}'::jsonb, anonymous_id=$3
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, `erased_${customerId}`],
    );
  }

  private async eraseDocuments(merchantId: string, customerId: string): Promise<void> {
    const manifests = await pool.query<{ object_key: string; document_type: string; metadata: Record<string, unknown> }>(
      `SELECT object_key, document_type, metadata FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    for (const manifest of manifests.rows) {
      if (manifest.document_type === 'customer_import') {
        try {
          await objectStore.removeObject(DOCUMENT_BUCKET, manifest.object_key);
        } catch {
          // Object may already be gone.
        }
        await pool.query(`DELETE FROM operations.document_manifests WHERE object_key=$1`, [manifest.object_key]);
        await pool.query(
          `DELETE FROM customers.customer_imports WHERE merchant_id=$1 AND object_key=$2`,
          [merchantId, manifest.object_key],
        );
        continue;
      }

      const anonymized = JSON.stringify(await this.anonymizedDocumentBody(manifest));
      await objectStore.putObject(
        DOCUMENT_BUCKET,
        manifest.object_key,
        anonymized,
        Buffer.byteLength(anonymized),
        { 'Content-Type': 'application/json' },
      );
      const checksum = createHash('sha256').update(anonymized).digest('hex');
      await pool.query(
        `UPDATE operations.document_manifests
         SET checksum=$2, metadata = COALESCE(metadata, '{}'::jsonb) - 'email' - 'name' - 'phone' - 'customer'
         WHERE object_key=$1`,
        [manifest.object_key, checksum],
      );
    }

    // Imports may exist without a customer_id on the manifest.
    const imports = await pool.query<{ id: string; object_key: string }>(
      `SELECT id, object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [merchantId],
    );
    for (const row of imports.rows) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, row.object_key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
        const content = Buffer.concat(chunks).toString('utf8');
        if (content.includes(customerId)) {
          await objectStore.removeObject(DOCUMENT_BUCKET, row.object_key);
          await pool.query(`DELETE FROM customers.customer_imports WHERE id=$1`, [row.id]);
          await pool.query(`DELETE FROM operations.document_manifests WHERE object_key=$1`, [row.object_key]);
        }
      } catch {
        // Missing objects are fine.
      }
    }
  }

  private async anonymizedDocumentBody(
    manifest: { object_key: string; document_type: string; metadata: Record<string, unknown> },
  ): Promise<Record<string, unknown>> {
    const customerId = String((manifest.metadata as { customerId?: string }).customerId ?? '');
    if (manifest.document_type === 'receipt') {
      return {
        receiptNumber: manifest.metadata.paymentId ?? manifest.object_key,
        issuedAt: new Date().toISOString(),
        customer: anonymizedCustomerSnapshot(customerId || 'unknown'),
        amount: manifest.metadata.amount ?? null,
        currency: manifest.metadata.currency ?? null,
        erased: true,
      };
    }
    if (manifest.document_type === 'invoice') {
      return {
        invoiceId: manifest.metadata.invoiceId ?? null,
        number: manifest.metadata.number ?? null,
        customer: anonymizedCustomerSnapshot(customerId || 'unknown'),
        erased: true,
      };
    }
    return { erased: true, objectKey: manifest.object_key };
  }

  private async eraseSearchAndCache(merchantId: string, customerId: string): Promise<void> {
    try {
      await searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${merchantId}:${customerId}`,
        refresh: true,
      });
    } catch (error) {
      const status = (error as { meta?: { statusCode?: number } }).meta?.statusCode;
      if (status !== 404) throw error;
    }

    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    await this.redis.del(cacheKey);
    await this.redis.del(`${cacheKey}:activity`);
  }

  private async eraseProvider(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email=$3, name=$4, external_reference=$5, updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId, erasedEmail(customerId), ANON_NAME, erasedExternalReference(customerId)],
    );
  }

  private async eraseOutboxPayloads(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.outbox_events
       SET payload = jsonb_strip_nulls(
         jsonb_build_object(
           'customerId', payload->'customerId',
           'paymentId', payload->'paymentId',
           'invoiceId', payload->'invoiceId',
           'refundId', payload->'refundId',
           'amount', payload->'amount',
           'currency', payload->'currency',
           'status', payload->'status',
           'paymentStatus', payload->'paymentStatus',
           'objectKey', payload->'objectKey',
           'number', payload->'number',
           'total', payload->'total',
           'erased', true
         )
       )
       WHERE merchant_id=$1
         AND (
           aggregate_id=$2
           OR payload->>'customerId'=$2
           OR (payload->'customer'->>'id')=$2
         )`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE operations.jobs
       SET payload = jsonb_set(
         COALESCE(payload, '{}'::jsonb),
         '{customerSnapshot}',
         $3::jsonb,
         true
       )
       WHERE merchant_id=$1 AND payload->>'customerId'=$2`,
      [merchantId, customerId, JSON.stringify(anonymizedCustomerSnapshot(customerId))],
    );

    await client.query(
      `UPDATE operations.dead_letters
       SET payload = COALESCE(payload, '{}'::jsonb) - 'email' - 'name' - 'phone' - 'customerEmail' - 'customer'
       WHERE payload->>'customerId'=$1 OR (payload->'customer'->>'id')=$1`,
      [customerId],
    );
  }

  private async eraseAuditLogs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE platform.audit_logs
       SET metadata='{}'::jsonb
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2`,
      [merchantId, customerId],
    );
  }
}

function stableErrorCode(error: unknown): string {
  if (!(error instanceof Error)) return 'erasure_failed';
  const message = error.message.toLowerCase();
  if (message.includes('mailpit')) return 'mailpit_cleanup_failed';
  if (message.includes('opensearch') || message.includes('index')) return 'search_cleanup_failed';
  if (message.includes('redis')) return 'cache_cleanup_failed';
  if (message.includes('minio') || message.includes('s3') || message.includes('object')) return 'document_cleanup_failed';
  if (message.includes('timeout')) return 'erasure_timeout';
  return 'erasure_failed';
}

export function startErasureWorker(signal: AbortSignal): { worker: ErasureWorker; done: Promise<void> } {
  const worker = new ErasureWorker();
  const done = (async () => {
    while (!signal.aborted) {
      try {
        const worked = await worker.tick();
        await new Promise((resolve) => setTimeout(resolve, worked ? 50 : 500));
      } catch (error) {
        logger.error({ error }, 'erasure worker loop failed');
        await new Promise((resolve) => setTimeout(resolve, 1_000));
      }
    }
    await worker.close();
  })();
  return { worker, done };
}
