    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',
           available_at=CASE WHEN $4::boolean THEN now() ELSE now() + make_interval(secs => $2::int) END,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           last_error=$3, updated_at=now()
       WHERE id=$1`,
      [requestId, exhausted ? 0 : delaySeconds, errorCode, exhausted],
    );
